// bundle.js -- build the extension as one file, dist/extension.js
// (specs/31-vsix-bundle.md R-1). `npm run bundle` runs it, and vsce runs that
// before packaging (vscode:prepublish), so every .vsix is the bundle.
//
// esbuild bundles src/extension.js and everything it requires but vscode. Then,
// from esbuild's metafile, this learns which npm packages went in and writes
// their license texts to dist/THIRD-PARTY-LICENSES.txt. It fails if one has no
// row at its version in THIRD-PARTY-NOTICES.md, or no license file.
'use strict';
const fs = require('fs');
const path = require('path');
const esbuild = require('esbuild');

const root = path.join(__dirname, '..');
const dist = path.join(root, 'dist');

// the npm package a bundled input belongs to: the innermost node_modules/<name>
// (or node_modules/@scope/name) in its path, with that folder
function packageOf(input) {
  const m = /^(.*node_modules\/((?:@[^/]+\/)?[^/]+))\//.exec(input.split(path.sep).join('/'));
  return m ? { name: m[2], folder: path.join(root, m[1]) } : null;
}

function licenseFile(folder) {
  const f = fs.readdirSync(folder).find((n) => /^licen[cs]e(\.(txt|md))?$/i.test(n));
  return f ? path.join(folder, f) : null;
}

async function main() {
  fs.rmSync(dist, { recursive: true, force: true });
  const result = await esbuild.build({
    absWorkingDir: root,
    entryPoints: ['src/extension.js'],
    outfile: 'dist/extension.js',
    bundle: true,
    platform: 'node',
    format: 'cjs',
    target: 'node20',      // VS Code 1.90's Node, the oldest the extension supports
    external: ['vscode'],
    minify: false,         // decision 1: a stack trace stays readable
    sourcemap: false,
    metafile: true,
    logLevel: 'warning',
  });
  fs.writeFileSync(path.join(dist, 'meta.json'), JSON.stringify(result.metafile, null, 1));

  // the bundled packages, by name@version
  const packages = new Map();
  for (const input of Object.keys(result.metafile.inputs)) {
    const p = packageOf(input);
    if (!p) continue;
    const version = JSON.parse(fs.readFileSync(path.join(p.folder, 'package.json'), 'utf8')).version;
    packages.set(p.name + '@' + version, { name: p.name, version, folder: p.folder });
  }

  const notices = fs.readFileSync(path.join(root, 'THIRD-PARTY-NOTICES.md'), 'utf8');
  const problems = [];
  const texts = [];
  for (const p of [...packages.values()].sort((a, b) => a.name.localeCompare(b.name))) {
    if (!notices.includes('| ' + p.name + ' | ' + p.version + ' |'))
      problems.push(p.name + ' ' + p.version + ' has no row in THIRD-PARTY-NOTICES.md');
    const file = licenseFile(p.folder);
    if (!file) { problems.push(p.name + ' ' + p.version + ' has no license file'); continue; }
    texts.push('='.repeat(78) + '\n' + p.name + ' ' + p.version + '\n' + '='.repeat(78) + '\n\n' +
               fs.readFileSync(file, 'utf8').replace(/\r\n/g, '\n').trim() + '\n');
  }
  if (problems.length) {
    for (const p of problems) console.error('bundle: ' + p);
    console.error('bundle: a package in the bundle needs a row in THIRD-PARTY-NOTICES.md and a license file');
    fs.rmSync(dist, { recursive: true, force: true });
    process.exit(1);
  }

  fs.writeFileSync(path.join(dist, 'THIRD-PARTY-LICENSES.txt'),
    'The license texts of the npm packages bundled, unchanged, into extension.js\n' +
    '(see THIRD-PARTY-NOTICES.md). Generated by scripts/bundle.js.\n\n' + texts.join('\n'));
  const size = fs.statSync(path.join(dist, 'extension.js')).size;
  console.log('bundle: dist/extension.js, ' + Math.round(size / 1024) + ' KB, with ' + packages.size + ' npm packages');
}

main().catch((e) => { console.error(e); process.exit(1); });
